// KHATMAH
function renderKhatmah() {
  const plan = KHATMAH.find(p => p.d === (S.khatDay||1)) || KHATMAH[0];
  const done = S.khatDone || {};
  const doneCount = Object.keys(done).length;
  const pct = Math.round((doneCount / 30) * 100);

  setEl('kh-pct', pct);
  setEl('kh-day-badge', `اليوم ${plan.d} من 30`);
  setEl('kh-juz-title', plan.t);
  setEl('kh-range', plan.r);
  const bar = document.getElementById('kh-bar');
  if (bar) bar.style.width = pct + '%';

  const doneBtn = document.getElementById('kh-done-btn');
  if (doneBtn) {
    if (done[plan.d]) { doneBtn.textContent = '✅ أكملت الجزء – مبارك!'; doneBtn.classList.add('done'); }
    else              { doneBtn.textContent = '✅ أكملت جزء اليوم (+100 نقطة)'; doneBtn.classList.remove('done'); }
  }

  const grid = document.getElementById('kh-grid');
  if (grid) {
    grid.innerHTML = '';
    KHATMAH.forEach(p => {
      const btn = document.createElement('button');
      btn.className = `kd-btn${done[p.d]?' kd-done':''}${p.d===S.khatDay?' kd-active':''}`;
      btn.textContent = p.d;
      btn.title = p.r;
      btn.onclick = () => { S.khatDay = p.d; saveS(); renderKhatmah(); };
      grid.appendChild(btn);
    });
  }
}

function openKhatmahReader() {
  const plan = KHATMAH.find(p => p.d === (S.khatDay||1)) || KHATMAH[0];
  openReader(plan.s);
  toast('📖 ' + plan.t + ': ' + plan.r);
}

function doneKhatmah() {
  const d = S.khatDay || 1;
  if (S.khatDone[d]) return;
  S.khatDone[d] = true;
  S.points = (S.points||0) + 100;
  S.checklist['ck-khatmah'] = true;
  if (d < 30) S.khatDay = d + 1;
  saveS(); renderKhatmah(); renderChecklist(); updateStreak();
  toast('تقبل الله! 🎉 جزاك الله خيراً (+100 نقطة)');
}

function resetKhatmah() {
  if (!confirm('إعادة الختمة من اليوم الأول؟')) return;
  S.khatDone = {}; S.khatDay = 1; S.checklist['ck-khatmah'] = false;
  saveS(); renderKhatmah(); renderChecklist();
  toast('تمت إعادة الختمة ✨');
}

