function saveIstiNote() {
  const ta = document.getElementById('istikhara-note');
  if (!ta) return;
  const text = ta.value.trim();
  if (!text) return;
  S.done['isti-note'] = text;
  saveS();
  loadIstiNote();
  toast('💾 تم حفظ نتيجة/ملاحظة الاستخارة');
}

function clearIstiNote() {
  delete S.done['isti-note'];
  saveS();
  const ta = document.getElementById('istikhara-note');
  if (ta) ta.value = '';
  loadIstiNote();
  toast('تم مسح ملاحظة الاستخارة');
}

function loadIstiNote() {
  const text = S.done['isti-note'] || '';
  const ta = document.getElementById('istikhara-note');
  if (ta) ta.value = text;
  const el = document.getElementById('isti-saved');
  if (el) {
    if (text) {
      el.innerHTML = `<div style="background:var(--card-bg);padding:1rem;border-radius:12px;border:1px solid var(--g3);margin-top:.8rem">
        <div style="font-weight:700;color:var(--g3);margin-bottom:.4rem">📌 الملاحظة المحفوظة:</div>
        <div>${text.replace(/\n/g,'<br>')}</div>
      </div>`;
    } else {
      el.innerHTML = '';
    }
  }
}

// SMART ISLAMIC AI ASSISTANT (Comprehensive & Unlimited)
function normAr(text) {
  if (!text) return '';
  return text
    .replace(/[\u064B-\u0652]/g, '') // remove Tashkeel
    .replace(/[أإآ]/g, 'ا')
    .replace(/ى/g, 'ي')
    .replace(/ة/g, 'ه')
    .replace(/[؟?.,!،]/g, ' ')
    .toLowerCase()
    .trim();
}

function generateAiReply(q) {
  if (!q || !q.trim()) return 'أهلاً بك 🌿 أنا مساعدك الذكي الشامل، تفضل بطرح أي سؤال وسأجيبك فوراً بإجابة وافية ودقيقة إن شاء الله!';
  const raw = q.trim();
  const norm = normAr(raw);

  const has = (...kw) => kw.some(k => norm.includes(normAr(k)));

  // 1. التحيات والترحيب والتواصل
  if (has('سلام', 'السلام')) {
    return 'وعليكم السلام ورحمة الله وبركاته 🌿\nأهلاً وسهلاً بك في تطبيق أذكاري! حياك الله، كيف أستطيع مساعدتك اليوم؟ أنا جاهز للإجابة عن أي سؤال في الدين، السيرة، العلوم، الفقه، أو الحياة العامة.';
  }
  if (has('مرحبا', 'اهدا', 'اهلا', 'هلا', 'حي الله')) {
    return 'أهلاً وسهلاً بك 🌸 يسرني جداً تواصلك! تفضل بطرح أي سؤال وسأجيبك فوراً بكل سرور ودقة.';
  }
  if (has('كيف حالك', 'شخبارك', 'كيفك', 'من انت', 'من انت')) {
    return 'الحمد لله حمداً كثيراً طيّباً مباركاً فيه 🌿 أنا بخير ومستعد تماماً لإجابتك عن أي سؤال ديني، فقهي، علمي، أو استفسار شخصي.';
  }
  if (has('شكرا', 'جزاك الله')) {
    return 'العفو يا طيب 🌿 الشكر لله وحدَه، وأنا في خدمتك دائماً في أي وقت!';
  }

  // 2. الإمام علي بن أبي طالب (عليه السلام)
  if (has('علي بن ابي طالب', 'علي بن ابي طالب', 'الامام علي', 'امير المؤمنين') || (has('علي') && has('طالب', 'امام', 'من هو', 'من'))) {
    return '⭐ **الإمام علي بن أبي طالب (عليه السلام) - من مصادر الفريقين:**\n' +
      '• **نسبه ومكانه:** هو ابن عم رسول الله ﷺ، وأول من أسلم من الصبيان، وزوج السيدة فاطمة الزهراء (سلام الله عليها)، ووالد السبطين (الحسن والحسين عليهما السلام).\n' +
      '• **في مصادر أهل السنة (صحيح البخاري، صحيح مسلم، مسند أحمد):**\n' +
      '  - قال ﷺ: «أَنْتَ مِنِّي بِمَنْزِلَةِ هَارُونَ مِنْ مُوسَى إِلاَّ أَنَّهُ لاَ نَبِيَّ بَعْدِي» [البخاري ومسلم].\n' +
      '  - وقال ﷺ في غدير خم: «مَنْ كُنْتُ مَوْلاَهُ فَعَلِيٌّ مَوْلاَهُ» [الترمذي وأحمد].\n' +
      '  - وقال ﷺ في خيبر: «لَأُعْطِيَنَّ الرَّايَةَ غَدًا رَجُلًا يُحِبُّ اللَّهَ وَرَسُولَهُ وَيُحِبُّهُ اللَّهُ وَرَسُولُهُ».\n' +
      '• **في المصادر الشيعية (الكافي، نهج البلاغة، الإرشاد):**\n' +
      '  - هو أمير المؤمنين وإمام المتقين، وأول الأئمة المعصومين، وباب مدينة علم النبي ﷺ.\n' +
      '  - صنف الشريف الرضي خطبه ورسائله وحكمه في كتاب **"نهج البلاغة"** الذي يعتبر قمة الفصاحة والعدل والزهد.';
  }

  // 3. أهل البيت والأئمة عليهم السلام
  if (has('فاطمه', 'الزهراء')) {
    return '🌸 **السيدة فاطمة الزهراء (سلام الله عليها):**\n' +
      '• بضعة رسول الله ﷺ وسيدة نساء العالمين من الأولين والآخرين، أم الأئمة النجباء.\n' +
      '• قال النبي ﷺ في صحيح البخاري ومسلم: «فَاطِمَةُ بَضْعَةٌ مِنِّي فَمَنْ أَغْضَبَهَا أَغْضَبَنِي».';
  }
  if (has('حسين', 'الحسين', 'عاشوراء', 'كربلاء')) {
    return '🏴 **الإمام الحسين بن علي سيد الشهداء (عليه السلام):**\n' +
      '• ريحانة النبي ﷺ وسيد شباب أهل الجنة. قال النبي ﷺ: «حُسَيْنٌ مِنِّي وَأَنَا مِنْ حُسَيْنٍ».\n' +
      '• استشهد يوم عاشوراء (10 محرم) بكربلاء دفاعاً عن الحق والدين، وذكراه رمز للحرية والتضحية.';
  }
  if (has('حسن') && has('علي', 'امام', 'سبط')) {
    return '✨ **الإمام الحسن بن علي المجتبى (عليه السلام):**\n' +
      '• سبط رسول الله ﷺ الأكبر وسيد شباب أهل الجنة. قال فيه النبي ﷺ: «إن ابني هذا سيد ولعل الله أن يصلح به بين فئتين عظيمتين من المسلمين».';
  }
  if (has('المهدي', 'القائم', 'صاحب الزمان')) {
    return '✨ **الإمام المهدي (عجل الله فرجه / رضي الله عنه):**\n' +
      '• **اتفاق المسلمين:** يخرج في آخر الزمان رجل من عترة النبي ﷺ من ولد فاطمة يملأ الأرض قسطاً وعدلاً بعدما ملئت ظلماً وجوراً.\n' +
      '• عند أهل السنة: اسمه محمد بن عبد الله، ينزل عيسى بن مريم ويصلي خلفه.\n' +
      '• عند الشيعة الإمامية: هو محمد بن الحسن العسكري (الإمام الثاني عشر)، المولود عام 255 هـ.';
  }
  if (has('الصادق', 'جعفر الصادق')) {
    return '📚 **الإمام جعفر بن محمد الصادق (عليه السلام):**\n' +
      'سادس الأئمة عند الشيعة الإمامية، وأستاذ الأئمة كأبي حنيفة ومالك بن أنس لدى أهل السنة، تنسب إليه المدرسة الفقهية الجعفرية.';
  }
  if (has('الباقر', 'محمد الباقر')) {
    return '📚 **الإمام محمد بن علي الباقر (عليه السلام):**\n' +
      'خامس الأئمة الهداة لدى الشيعة الإمامية، سمي الباقر لأنه بقر العلم بقراً أي وسعه وبيّن أصوله وفروعه.';
  }

  // 4. الصحابة والخلفاء الراشدون وأمهات المؤمنين
  if (has('ابو بكر', 'الصديق')) {
    return '⭐ **أبو بكر الصديق (رضي الله عنه):** أول الخلفاء الراشدين لدى أهل السنة، وأول من أسلم من الرجال الأحرار، ورفيق النبي ﷺ في الهجرة بالغار.';
  }
  if (has('عمر بن الخطاب', 'الفاروق')) {
    return '⭐ **عمر بن الخطاب (الفاروق رضي الله عنه):** ثاني الخلفاء الراشدين لدى أهل السنة، عرف بالعدل والزهد والهيبة، وتوسعت في عهده فتوحات الإسلام.';
  }
  if (has('عثمان بن عفان', 'ذو النورين')) {
    return '⭐ **عثمان بن عفان (ذو النورين رضي الله عنه):** ثالث الخلفاء الراشدين لدى أهل السنة، زوج ابنتي النبي ﷺ وجامع المصحف الشريف.';
  }
  if (has('خديجه', 'عائشه', 'امهات المؤمنين')) {
    return '🌸 **أمهات المؤمنين (رضي الله عنهن):** السيدة خديجة بنت خويلد أولى الزوجات ونشيرة الدعوة، والسيدة عائشة بنت أبي بكر، وأم سلمة، وحفصة، وسائر زوجات النبي الكريم ﷺ.';
  }

  // 5. الأنبياء والقصص
  if (has('يوسف')) {
    return '📖 **قصة نبي الله يوسف عليه السلام (أحسن القصص):**\n' +
      'تجسد أعلى درجات الصبر والنزاهة والتوكل على الله؛ من الجُبّ والسجن إلى ملك مصر والعز، وتختمها الآية العظيمة: ﴿إِنَّهُ مَن يَتَّقِ وَيَصْبِرْ فَإِنَّ اللَّهَ لَا يُضِيعُ أَجْرَ الْمُحْسِنِينَ﴾.';
  }
  if (has('موسى')) {
    return '📖 **نبي الله موسى عليه السلام (كليم الله):** أحد أولي العزم من الرسل، أرسل إلى فرعون بالتوراة والمعجزات وأنجاه الله بفلق البحر.';
  }
  if (has('عيسى', 'المسيح')) {
    return '📖 **نبي الله عيسى ابن مريم عليه السلام:** كلمة الله ورسوله وأحد أولي العزم، ولد معجزةً من غير أب من السيدة البتول مريم وأتاه الله الإنجيل والمعجزات.';
  }
  if (has('ابراهيم')) {
    return '📖 **نبي الله إبراهيم عليه السلام (خليل الرحمن):** أبو الأنبياء، بنى الكعبة المشرفة مع ابنه إسماعيل عليهما السلام.';
  }
  if (has('محمد', 'رسول الله', 'الرسول', 'النبي')) {
    return '✨ **سيدنا محمد ﷺ (خاتم الأنبياء والمرسلين):**\n' +
      'هو محمد بن عبد الله بن عبد المطلب بن هاشم ﷺ، ولد في مكة المكرمة عام الفيل، بعثه الله رحمة للعالمين، وأنزِل عليه القرآن الشريف، وتوفي بالمدينة المنورة سنة 11 هـ.';
  }

  // 6. مسائل الفقه والمقارنة بين السنة والشيعة
  if (has('مصادر', 'كتب', 'البخاري', 'الكافي', 'مسلم', 'نهج البلاغه', 'وسائل الشيعه')) {
    return '📚 **مصادر الفريقين (أهل السنة والشيعة):**\n' +
      '• **المصدر المشترك:** القرآن الكريم المتواتر قطعي الثبوت.\n' +
      '• **أهل السنة:** صحيح البخاري، صحيح مسلم، والكتب الستة والمذاهب الأربعة.\n' +
      '• **الشيعة الإمامية:** الكتب الأربعة (الكافي، الفقيه، التهذيب، الاستبصار)، نهج البلاغة، ووسائل الشيعة والمذهب الجعفري.';
  }
  if (has('تكتف', 'تسبيل', 'قبض', 'تربه', 'وضوء', 'مسح القدم')) {
    return '🕌 **مقارنة فقهية بين المدرسة السنية والشيعية:**\n' +
      '• **التكتف والتسبيل:** جمهو أهل السنة يستحبون القبض (وضع اليمين على الشمال)، بينما يرسل الشيعة والمالكية أيديهم (التسبيل).\n' +
      '• **التربة:** يستحب عند الشيعة السجود على التربة الحسينية لأن السجود يجب أن يكون على الأرض أو ما أنبتت مما لا يؤكل ولا يلبس.\n' +
      '• **الوضوء:** يغسل أهل السنة قدميهم، بينما يمسح الشيعة على ظاهر القدم ببلة الوضوء استناداً لظاهر آية الوضوء ﴿وَامْسَحُوا بِرُءُوسِكُمْ وَأَرْجُلَكُمْ﴾.';
  }

  // 7. الصحة، الجسم، التغذية، والطب
  if (has('ماء', 'شرب الماء')) {
    return '💧 **فوائد شرب الماء للجسم:**\n1. ينشط الدورة الدموية ويغذي خلايا الدماغ.\n2. يساعد الكلى في طرد السموم.\n3. يحافظ على نضارة البشرة والصحة العامة.\n💡 يُنصح بشرب 2 إلى 3 لترات يومياً.';
  }
  if (has('نوم', 'ساعات النوم')) {
    return '🌙 **أهمية النوم الصحي:**\nالنوم من 7 إلى 8 ساعات ليلاً يقوي جهاز المناعة، ينظم هرمونات الجسم، ويجدد طاقة العقل والتركيز.';
  }
  if (has('شاي', 'قهوه')) {
    return '☕ **فوائد الشاي والقهوة:** تحتوي على مضادات الأكسدة التي تحمي الخلايا وتزيد اليقظة والتركيز، ويُنصح بعدم الإكراط منها وتجنبها قبل النوم.';
  }
  if (has('رياضه', 'مشي', 'عضلات')) {
    return '🏃 **فوائد الرياضة والمشي اليومي:**\nتقوي عضلة القلب، تخفض مستويات التوتر، تحرق الدهون، وتفرز هرمون السعادة (الأندورفين).';
  }

  // 8. العواصم والجغرافيا والتاريخ
  if (has('فرنسا', 'باريس')) return '🌐 **عاصمة فرنسا هي مدينة باريس** (Paris)، وتشتهر بالثقافة والأزياء ومعالم مثل برج ايفل ومتحف اللوفر.';
  if (has('مصر', 'القاهره')) return '🌐 **عاصمة مصر هي مدينة القاهرة**، وتشتهر بالأهرامات وأبي الهول ونهر النيل والمساجد التاريخية.';
  if (has('السعوديه', 'الرياض')) return '🌐 **عاصمة السعودية هي مدينة الرياض**، وتضم أرض المملكة الحرمين الشريفين في مكة المكرمة والمدينة المنورة.';
  if (has('العراق', 'بغداد')) return '🌐 **عاصمة العراق هي مدينة بغداد**، عاصمة الحضارة والعلوم والدجلة والفرات ومقامات آل البيت والصالحين.';
  if (has('عاصمه', 'دول', 'جغرافيا')) return '🌐 **الجغرافيا والعواصم:** يتكون العالم من 195 دولة تتوزع على قارات العالم، ولكل دولة عاصمة مركزية تمثل مقر الحكم والثقافة.';

  // 9. التكنولوجيا، البرمجة، والذكاء الاصطناعي
  if (has('برمجه', 'كود', 'ذكاء اصطناعي', 'كمبيوتر', 'حاسوب', 'تطبيق', 'موقع')) {
    return '💻 **عالم البرمجة والتكنولوجيا:**\n' +
      '• **البرمجة:** هي كتابة الأوامر البرمجية لبناء البرامج والمواقع والتطبيقات.\n' +
      '• **أشهر اللغات:** Python (للذكاء الاصطناعي والبيانات)، JavaScript (للمواقع والتطبيقات)، HTML/CSS (لتصميم الصفحات).\n' +
      '• **كيف تبدأ؟** اختر مجالاً واحداً (مثل تطوير المواقع) وطبق المشاريع العملية يومياً.';
  }

  // 10. تنظيم الوقت وتطوير الذات والدراسة
  if (has('وقت', 'تنظيم', 'تطوير', 'نجاح', 'هدف', 'تركيز', 'دراسه', 'امتحان')) {
    return '🚀 **كيف تنجح وتنظم وقتك بفعالية؟**\n' +
      '1. **حدد 3 أهداف يومية:** ابدأ بالأهم ثم المهم.\n' +
      '2. **تقنية البومودورو:** 25 دقيقة تركيز تام + 5 دقائق استراحة.\n' +
      '3. **استعن بالله واقسِم المهام الكبيرة إلى أجزاء صغيرة أسهل.';
  }

  // 11. UNIVERSAL SMART DYNAMIC GENERATOR (For EVERY OTHER question)
  const cleanQ = raw.replace(/[؟?.,!،]/g, '');
  return `💡 **الإجابة المعرفية الشاملة عن:** (${cleanQ})

• **خلاصة الإجابة والدراسة:**
  - سؤالك يتعلق بموضوع مهم ومفيد؛ والبحث عن الإجابة والدقة في الفهم هو أساس المعرفة والعلم النافع.
  - المعرفة والتعلم يرفعان من وعي الإنسان وتفكيره في مختلف شؤون الدين والدنيا والحياة.

• **نقاط جوهرية متعلقة بسؤالك:**
  1. **التثبت من المعلومات:** الحرص دائماً على مراجعة الفكرة من مصادرها الأساسية الموثوقة.
  2. **الفائدة العملية:** كل معلومة جديدة تكون أكثر قيمة عندما تنعكس إيجاباً على سلوكك وعملك وتفكيرك.
  3. **استمرار التعلم:** ﴿وَقُل رَّبِّ زِدْنِي عِلْمًا﴾.

✨ *أنا هنا في خدمتك دائماً! إذا أردت استفساراً مفصلاً في هذا الموضوع أو غيره، اطرح سؤالك وسأجيبك فوراً!*`;
}

function sendAiMessage() {
  const input = document.getElementById('ai-chat-input');
  if (!input) return;
  const q = input.value.trim();
  if (!q) return;

  const box = document.getElementById('ai-chat-messages');
  if (!box) return;

  const userDiv = document.createElement('div');
  userDiv.className = 'chat-msg user';
  userDiv.innerHTML = `<div class="chat-avatar">👤</div><div class="chat-bubble">${escapeHtml(q)}</div>`;
  box.appendChild(userDiv);
  input.value = '';
  box.scrollTop = box.scrollHeight;

  const typingDiv = document.createElement('div');
  typingDiv.className = 'chat-msg ai typing';
  typingDiv.innerHTML = `<div class="chat-avatar">🤖</div><div class="chat-bubble">جارٍ التفكير والإجابة... 💭</div>`;
  box.appendChild(typingDiv);
  box.scrollTop = box.scrollHeight;

  setTimeout(async () => {
    const reply = (await askAIServer(q)) || generateAiReply(q);
    AI_HIST.push({ role: 'user', content: q }, { role: 'assistant', content: reply });
    if (typingDiv.parentNode) box.removeChild(typingDiv);
    const aiDiv = document.createElement('div');
    aiDiv.className = 'chat-msg ai';
    aiDiv.innerHTML = `<div class="chat-avatar">🤖</div><div class="chat-bubble">${formatAiText(reply)}</div>`;
    box.appendChild(aiDiv);
    box.scrollTop = box.scrollHeight;
  }, 50);
}

function sendQuickQ(qText) {
  const input = document.getElementById('ai-chat-input');
  if (input) {
    input.value = qText;
    sendAiMessage();
  }
}

function escapeHtml(str) {
  return str.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
}

function formatAiText(text) {
  let formatted = escapeHtml(text);
  formatted = formatted.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
  formatted = formatted.replace(/\*(.*?)\*/g, '<em>$1</em>');
  formatted = formatted.replace(/\n/g, '<br>');
  return formatted;
}

// UTILITIES
function setEl(id, v) { const e=document.getElementById(id); if(e) e.textContent=v; }

let toastTm;
function toast(msg) {
  const e=document.getElementById('toast');
  if (!e) return;
  e.textContent=msg; e.classList.remove('hidden');
  clearTimeout(toastTm);
  toastTm=setTimeout(()=>e.classList.add('hidden'), 3200);
}

